import { Audio, Sequence, staticFile } from "remotion";

export type SfxName =
  | "whoosh"
  | "whoosh-short"
  | "swish-reverse"
  | "impact"
  | "sub-drop"
  | "click"
  | "tick"
  | "pop"
  | "riser"
  | "shimmer"
  | "type"
  | "glitch";

/** One sound effect placed at a frame. Files live in public/sfx (generated by scripts/make-sfx.py). */
export const Sfx: React.FC<{ name: SfxName; at: number; volume?: number }> = ({ name, at, volume = 0.6 }) => (
  <Sequence from={at} layout="none">
    <Audio src={staticFile(`sfx/${name}.wav`)} volume={volume} />
  </Sequence>
);

/**
 * Background music bed from public/music. Place it inside a <Sequence> to start it later;
 * `durationInFrames` is how long it plays from there. Fades are in frames.
 */
export const Music: React.FC<{
  file: string;
  durationInFrames: number;
  volume?: number;
  fadeIn?: number;
  fadeOut?: number;
  startFrom?: number;
}> = ({ file, durationInFrames, volume = 0.5, fadeIn = 15, fadeOut = 60, startFrom = 0 }) => (
  <Audio
    src={staticFile(`music/${file}`)}
    startFrom={startFrom}
    volume={(f) => volume * Math.max(0, Math.min(1, f / fadeIn, (durationInFrames - f) / fadeOut))}
  />
);
